<!doctype html><html><head><meta charset="utf-8"><title>{{ $bill->bill_number }}</title><style>body{font:14px monospace;width:300px;margin:20px auto;color:#111}h1,p{text-align:center;margin:5px}table{width:100%;border-collapse:collapse}td,th{padding:5px 0;border-bottom:1px dashed #999;text-align:left}.right{text-align:right}.total{font-size:18px;font-weight:bold}button{width:100%;padding:10px;margin-top:18px}@media print{button{display:none}body{margin:0}}</style></head><body><h1>{{ $settings?->restaurant_name??'TablePlay' }}</h1><p>{{ $settings?->address }}<br>{{ $settings?->phone }}</p><hr><p>{{ $bill->bill_number }}<br>Table {{ $bill->tableSession->diningTable->table_code }} · {{ $bill->generated_at->format('d M Y H:i') }}</p><table><tr><th>Item</th><th class="right">Amount</th></tr>@foreach($bill->tableSession->orders->whereNotIn('status',['cancelled','rejected']) as $order)@foreach($order->items->where('status','!=','cancelled') as $item)<tr><td>{{ $item->quantity }} × {{ $item->item_name_snapshot }}</td><td class="right">{{ number_format($item->line_total,2) }}</td></tr>@endforeach @endforeach<tr><td>Subtotal</td><td class="right">{{ $bill->subtotal }}</td></tr><tr><td>{{ $settings?->tax_name??'Tax' }}</td><td class="right">{{ $bill->tax_amount }}</td></tr><tr><td>Discount</td><td class="right">-{{ $bill->discount_amount }}</td></tr><tr class="total"><td>Total</td><td class="right">{{ $settings?->currency??'INR' }} {{ $bill->grand_total }}</td></tr>@if($bill->payment_status==='paid')<tr><td>Cash received</td><td class="right">{{ $bill->payments->sum('received_amount') }}</td></tr><tr><td>Change</td><td class="right">{{ $bill->payments->sum('change_amount') }}</td></tr>@endif</table><p>{{ $settings?->receipt_footer??'Thank you for dining with us.' }}</p><button onclick="window.print()">Print receipt</button></body></html>
